-- 0074_translate_content_de.sql
-- Фаза 28: перевод контента программ — немецкий (de).
-- Переведено вручную с русского оригинала (с опорой на вычитанный
-- английский), с терминологией, принятой в залах этой страны. Английские
-- названия упражнений (Hip Thrust, Mountain Climbers…) оставлены как есть.
-- Применять после 0072. Сопоставление — по точному русскому тексту.
-- Безопасно выполнять повторно.

update public.workout_programs p
set title_de = v.title, description_de = v.description
from (values
  ('pohudenie-zhenshchiny-doma', 'Abnehmen · Frauen · Zuhause', 'Abnehmen für Frauen (zu Hause) — DonatelleX, Jahresprogramm. Ausrüstung: Kurzhanteln, Widerstandsbänder in verschiedenen Stärken, Matte, stabile Plattform/Stufe (wenn vorhanden)'),
  ('pohudenie-zhenshchiny-zal', 'Abnehmen · Frauen · Studio', 'Abnehmen für Frauen (im Studio) — Jahresprogramm. Ausrüstung: Laufband, Crosstrainer/SkiErg, Maschinen, Kurzhanteln, Kabelzug, Matte'),
  ('nabor-massy-zhenshchiny-doma', 'Muskelaufbau · Frauen · Zuhause', 'Muskelaufbau für Frauen (zu Hause) — Jahresprogramm. Ausrüstung: Kurzhanteln, Widerstandsbänder in verschiedenen Stärken, Matte, stabile Plattform/Stufe'),
  ('nabor-massy-zhenshchiny-zal', 'Muskelaufbau · Frauen · Studio', 'Muskelaufbau für Frauen (im Studio) — Jahresprogramm «12 LEVELS». Ausrüstung: Langhantel, Kurzhanteln, Maschinen (Hip Thrust, Hack Squat, Beinpresse, Kabelzug), Widerstandsbänder, Kettlebells, TRX, Medizinball'),
  ('pohudenie-muzhchiny-doma', 'Abnehmen · Männer · Zuhause', 'Abnehmen für Männer (zu Hause) — Jahresprogramm. Ausrüstung: Kurzhanteln, Widerstandsbänder, Klimmzugstange (wenn vorhanden), Stuhl/Bank, Matte'),
  ('pohudenie-muzhchiny-zal', 'Abnehmen · Männer · Studio', 'Abnehmen für Männer (im Studio) — Jahresprogramm. Ausrüstung: Langhantel, Kurzhanteln, Maschinen, Kabelzug, Battle Rope, SkiErg/Rudergerät, Cardiobereich (Laufband/Crosstrainer/Ergometer)'),
  ('nabor-massy-muzhchiny-doma', 'Muskelaufbau · Männer · Zuhause', 'Muskelaufbau für Männer (zu Hause) — Jahresprogramm. Ausrüstung: Kurzhanteln, Widerstandsbänder, Klimmzugstange (wenn vorhanden), Stuhl/Bank, Matte'),
  ('nabor-massy-muzhchiny-zal', 'Muskelaufbau · Männer · Studio', 'Muskelaufbau für Männer (im Studio) — Jahresprogramm. Ausrüstung: Komplettes Studio: Langhanteln, Kurzhanteln, Maschinen, Klimmzugstange, Seile, TRX, Kettlebells'),
  ('nabor-massy-nachinayushchim', 'Muskelaufbau für Einsteiger', 'Das erste Programm für Männer, die im Studio mit dem Muskelaufbau beginnen wollen. 7-Tage-Zyklus: 4 Krafteinheiten für verschiedene Muskelgruppen und 3 Tage leichtes Cardio mit Bauchtraining. Für Einsteiger geeignet — keine komplizierte Technik, Fokus auf Volumen und saubere Ausführung.')
) as v(slug, title, description)
where p.slug = v.slug;

